/// Whether ExifTool stores the `ilst` item of code `atom` at priority 0 when the
/// list is an iTunes item list (`QuickTime::ItemList`).
pub fn item_list_is_priority0(atom: &[u8]) -> bool {
    ITEM_LIST_PRIORITY0.binary_search(&atom).is_ok()
}

/// Whether ExifTool stores the `udta` atom `atom` at priority 0
/// (`QuickTime::UserData`).
pub fn user_data_is_priority0(atom: &[u8]) -> bool {
    USER_DATA_PRIORITY0.binary_search(&atom).is_ok()
}

/// Whether ExifTool stores the `Keys` metadata key `key` at priority 0
/// (`QuickTime::Keys`).
pub fn keys_is_priority0(key: &[u8]) -> bool {
    KEYS_PRIORITY0.binary_search(&key).is_ok()
}

/// Whether a MakerNote Main-table tag is stored at priority 0.
///
/// ExifTool marks a handful of them unreliable -- Sony's 0xb04f
/// DynamicRangeOptimizer is noted as wrong on the A77 -- and a priority-0
/// duplicate never displaces a value already stored under that name.
#[must_use]
pub fn makernote_is_priority0(maker: &str, id: u16) -> bool {
    matches!((maker, id),
        ("Casio", 0x0014)
        | ("FujiFilm", 0x1431)
        | ("Nikon", 0x0002)
        | ("Olympus", 0x1000)
        | ("Olympus", 0x1001)
        | ("Olympus", 0x1002)
        | ("Olympus", 0x1003)
        | ("Olympus", 0x100f)
        | ("Olympus", 0x0207)
        | ("Pentax", 0x008b)
        | ("Pentax", 0x0012)
        | ("Pentax", 0x0013)
        | ("Pentax", 0x001d)
        | ("Sigma", 0x0018)
        | ("Sigma", 0x0031)
        | ("Sigma", 0x0032)
        | ("Sigma", 0x003b)
        | ("Sigma", 0x003c)
        | ("Sigma", 0x0049)
        | ("Sigma", 0x004a)
        | ("Sigma", 0x0057)
        | ("Sigma", 0x0058)
        | ("Sony", 0xb04f)
        | ("Sony", 0x201b)
    )
}
